# RDEB-SCC: robust integration of three DESeq2 DEG lists
# Input files should be Significant_DEGs.csv generated by 01_deseq2_three_group.R.
# The script writes both a strict three-comparison intersection and a union.
# NOTE: a shared gene identifier is essential; do not mix gene symbols and Ensembl IDs.

suppressPackageStartupMessages(library(readr))

# ---------------- USER SETTINGS ----------------
base_dir <- "D:/final rdeb - scc/DESeq2_corrected"
file_RDEB_Healthy <- file.path(base_dir, "RDEB_vs_Healthy", "Significant_DEGs.csv")
file_SCC_Healthy  <- file.path(base_dir, "SCC_vs_Healthy", "Significant_DEGs.csv")
file_SCC_RDEB     <- file.path(base_dir, "SCC_vs_RDEB", "Significant_DEGs.csv")
outdir <- file.path(base_dir, "Integrated_Genes")
# ------------------------------------------------

dir.create(outdir, recursive = TRUE, showWarnings = FALSE)
inputs <- list(
  RDEB_vs_Healthy = file_RDEB_Healthy,
  SCC_vs_Healthy = file_SCC_Healthy,
  SCC_vs_RDEB = file_SCC_RDEB
)
for (nm in names(inputs)) if (!file.exists(inputs[[nm]])) stop("Missing input for ", nm, ": ", inputs[[nm]])

read_deg <- function(path, label) {
  dat <- read_csv(path, show_col_types = FALSE, name_repair = "minimal")
  if (nrow(dat) == 0) warning(label, " has zero rows. Check the upstream DESeq2 result and thresholds.")
  dat <- as.data.frame(dat, check.names = FALSE)
  # Find likely gene identifier columns; prioritize symbols when all files have them,
  # otherwise prefer a shared identifier column name across all files.
  names_norm <- tolower(gsub("[^a-z0-9]", "", names(dat)))
  dat$.source_label <- label
  attr(dat, "original_names") <- names(dat)
  attr(dat, "normalized_names") <- names_norm
  dat
}

raw <- lapply(names(inputs), function(nm) read_deg(inputs[[nm]], nm))
names(raw) <- names(inputs)
key_candidates <- c("genesymbol", "gene", "geneid", "ensembl", "ensemblid", "id")
normalized <- lapply(raw, function(d) tolower(gsub("[^a-z0-9]", "", names(d))))
common_names <- Reduce(intersect, normalized)
key_norm <- key_candidates[key_candidates %in% common_names][1]
if (is.na(key_norm) || length(key_norm) == 0) {
  stop("Could not find a shared gene identifier column across all three files. Columns are: ",
       paste(names(raw), paste(vapply(raw, function(d) paste(names(d), collapse = "/"), character(1)), sep = "=[", collapse = "]; "),
       ". Ensure all files share the same identifier column, e.g. GeneID, GeneSymbol, or ENSEMBL.")
}
key_cols <- vapply(seq_along(raw), function(i) names(raw[[i]])[match(key_norm, normalized[[i]])], character(1))
message("Using shared gene identifier: ", key_norm, " (columns: ", paste(key_cols, collapse = ", "), ")")

get_ids <- function(d, key_col) {
  ids <- trimws(as.character(d[[key_col]]))
  ids <- ids[!is.na(ids) & ids != "" & ids != "NA"]
  unique(ids)
}
gene_sets <- Map(get_ids, raw, as.list(key_cols))
names(gene_sets) <- names(inputs)

# Strict intersection = genes significant in all three contrasts.
common_genes <- Reduce(intersect, gene_sets)
# Union = genes significant in at least one contrast.
all_genes <- sort(unique(unlist(gene_sets, use.names = FALSE)))

write.csv(data.frame(GeneID = sort(common_genes)), file.path(outdir, "Common_DEGs_All_Three_Contrasts.csv"), row.names = FALSE)
write.csv(data.frame(GeneID = all_genes), file.path(outdir, "Union_DEGs_Any_Contrast.csv"), row.names = FALSE)

membership <- data.frame(GeneID = all_genes, stringsAsFactors = FALSE)
for (nm in names(gene_sets)) membership[[nm]] <- membership$GeneID %in% gene_sets[[nm]]
membership$NumberOfContrasts <- rowSums(membership[, names(gene_sets), drop = FALSE])
write.csv(membership, file.path(outdir, "DEG_Contrast_Membership.csv"), row.names = FALSE)

summary_df <- data.frame(
  Contrast = names(gene_sets),
  Significant_gene_count = vapply(gene_sets, length, integer(1)),
  stringsAsFactors = FALSE
)
summary_df <- rbind(summary_df, data.frame(Contrast = "Strict intersection (all 3)", Significant_gene_count = length(common_genes)),
                    data.frame(Contrast = "Union (any 1+)", Significant_gene_count = length(all_genes)))
write.csv(summary_df, file.path(outdir, "Integration_Summary.csv"), row.names = FALSE)

message("Significant genes by contrast:")
print(summary_df)
message("Integration complete. The strict intersection and union are separate outputs; neither is automatically the final 91-gene candidate set.")
